/**
 * Tests for AddressVerificationService.
 *
 * The tests pin down the documented behaviour, including the API contract of the outgoing
 * request (POST callout:FB_Address_API/v2/verify, Content-Type: application/json and the JSON
 * body {"street", "city", "postalCode", "country"}). The callout mock asserts the request
 * contract for every callout, so every test that performs a callout also verifies the request.
 *
 * The tests are self-contained (no SeeAllData, no org data). No DML is performed before a
 * callout: the account handed to verify() is deliberately never inserted. The documented
 * "corrected in memory, not saved" behaviour is therefore proven by asserting that verify()
 * performs no DML at all and that no Account row exists afterwards (a save attempt would either
 * show up in Limits.getDmlStatements()/the query or blow up with a DmlException).
 */
@IsTest
private class AddressVerificationServiceTest {

    private static final String EXPECTED_ENDPOINT = 'callout:FB_Address_API/v2/verify';
    private static final String TEST_ACCOUNT_NAME = 'AddressVerificationServiceTest';

    // ------------------------------------------------------------------
    // Blank BillingStreet -> SKIPPED, no callout
    // ------------------------------------------------------------------

    @IsTest
    static void blankBillingStreetIsSkippedWithoutCallout() {
        assertSkippedNoCallout(null);
        assertSkippedNoCallout('');
        assertSkippedNoCallout('   ');
    }

    // ------------------------------------------------------------------
    // 200 responses
    // ------------------------------------------------------------------

    @IsTest
    static void verifiedResponseReturnsStatusAndLeavesAccountUntouched() {
        Account acct = makeAccount('123 Main St', 'Austin', '78701', 'US');
        RecordingCalloutMock mock = new RecordingCalloutMock(
            200,
            jsonResponse('VERIFIED', '456 Oak Ave', 'Dallas', '75201', 'USA'),
            expectedBodyFor(acct)
        );
        Test.setMock(HttpCalloutMock.class, mock);

        Integer dmlBefore = Limits.getDmlStatements();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        System.assertEquals('VERIFIED', result.status,
            'result.status must be the status returned by the API');
        System.assertEquals(false, result.changed,
            'result.changed must be false unless the response status is CORRECTED');
        assertBillingFields(acct, '123 Main St', 'Austin', '78701', 'US',
            'A VERIFIED response must leave the account untouched');
        assertNothingPersisted(dmlBefore, acct,
            'A VERIFIED response must not save the account');
        System.assertEquals(1, mock.requests.size(), 'Exactly one callout is expected');
    }

    @IsTest
    static void invalidResponseReturnsStatusAndLeavesAccountUntouched() {
        Account acct = makeAccount('123 Main St', 'Austin', '78701', 'US');
        RecordingCalloutMock mock = new RecordingCalloutMock(
            200,
            jsonResponse('INVALID', '789 Pine Rd', 'Houston', '77002', 'USA'),
            expectedBodyFor(acct)
        );
        Test.setMock(HttpCalloutMock.class, mock);

        Integer dmlBefore = Limits.getDmlStatements();
        AddressVerificationService.Result result = AddressVerificationService.verify(acct);

        System.assertEquals('INVALID', result.status,
