    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the finalizer before any work so every run is logged and retried.
        System.attachFinalizer(new ErpSyncFinalizer(this.accountIds, this.attempt));

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : this.accountIds) {
            accountsToUpdate.add(new Account(
                Id = accountId,
                Description = SYNC_DESCRIPTION
            ));
        }

        // All-or-nothing: a single failure throws and rolls back the whole job.
        Database.update(accountsToUpdate, true);
    }
}
