public with sharing class ErpSyncFinalizer implements Finalizer {
    private static final String JOB_NAME = 'ErpAccountSyncJob';
    private static final String STATUS_SUCCESS = 'Success';
    private static final String STATUS_FAILED = 'Failed';
    private static final String RESULT_SUCCESS = 'SUCCESS';
    private static final String RESULT_UNHANDLED_EXCEPTION = 'UNHANDLED_EXCEPTION';
    private static final Integer MAX_ATTEMPT = 3;
    private static final Integer ERROR_MAX_LENGTH = 255;

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(FinalizerContext context) {
        Boolean succeeded = hasSucceeded(context);

        FB_Job_Log__c jobLog = new FB_Job_Log__c(
            Job_Name__c = JOB_NAME,
            Status__c = succeeded ? STATUS_SUCCESS : STATUS_FAILED,
            Attempt__c = this.attempt
        );

        if (!succeeded) {
            jobLog.Error__c = truncateErrorMessage(context.getException());
        }

        insert jobLog;

        if (!succeeded && this.attempt < MAX_ATTEMPT) {
            System.enqueueJob(new ErpAccountSyncJob(this.accountIds, this.attempt + 1));
        }
    }

    private static Boolean hasSucceeded(FinalizerContext context) {
        // The job result is compared by name so the class compiles regardless of how the
        // platform exposes the result type, and falls back to the reported exception.
        String resultName = String.valueOf(context.getResult());
        if (resultName == RESULT_SUCCESS) {
            return true;
        }
        if (resultName == RESULT_UNHANDLED_EXCEPTION) {
            return false;
        }
        return context.getException() == null;
    }

    private static String truncateErrorMessage(Exception jobException) {
        if (jobException == null) {
            return null;
        }

        String errorMessage = jobException.getMessage();
        if (errorMessage != null && errorMessage.length() > ERROR_MAX_LENGTH) {
            errorMessage = errorMessage.substring(0, ERROR_MAX_LENGTH);
        }
        return errorMessage;
    }
}
