/**
 * Pushes every newly created Account to the ERP as a customer.
 *
 * The ERP expects one POST per customer (body: JSON array with one element) so it
 * can trace every account on its own. Callouts are not supported in trigger
 * context, and a transaction may perform at most 100 callouts while a
 * marketplace insert can hold 200 accounts. AccountTrigger therefore enqueues
 * one Queueable per 100 accounts; every job sends one request per account.
 *
 * Jobs are enqueued from the trigger only and are never chained from another
 * job, so the queueable chaining limits cannot be hit.
 *
 * Error handling and retries are out of scope for this ticket.
 */
public with sharing class ErpCustomerSync implements Queueable, Database.AllowsCallouts {

    private static final String ENDPOINT = 'callout:ERP/api/customers';
    private static final Integer HTTP_ACCEPTED = 202;
    /** One request per customer; at most 100 callouts are allowed per transaction. */
    private static final Integer MAX_REQUESTS_PER_JOB = 100;

    private List<Customer> customers;

    public ErpCustomerSync(List<Customer> customers) {
        this.customers = (customers == null) ? new List<Customer>() : customers;
    }

    /** Entry point for AccountTrigger: one job per 100 created accounts. */
    public static void enqueue(List<Account> newAccounts) {
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }

        List<Customer> chunk = new List<Customer>();
        for (Account account : newAccounts) {
            chunk.add(new Customer(account));
            if (chunk.size() == MAX_REQUESTS_PER_JOB) {
                System.enqueueJob(new ErpCustomerSync(chunk));
                chunk = new List<Customer>();
            }
        }
        if (!chunk.isEmpty()) {
            System.enqueueJob(new ErpCustomerSync(chunk));
        }
    }

    public void execute(QueueableContext context) {
        for (Customer customer : customers) {
            postCustomer(customer);
        }
    }

    private static void postCustomer(Customer customer) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(ENDPOINT);
        request.setMethod('POST');
        request.setHeader('Content-Type', 'application/json');
        request.setBody(buildBody(customer));

        HttpResponse response = new Http().send(request);

        // The ERP acknowledges with 202 Accepted; error handling/retries are out of scope.
        if (response.getStatusCode() != HTTP_ACCEPTED) {
            System.debug(
                LoggingLevel.ERROR,
                'ERP customer sync failed for ' + customer.salesforceId +
                ' with status ' + String.valueOf(response.getStatusCode()) +
                ': ' + response.getBody()
            );
        }
    }

    /** The ERP takes a JSON array, so a single customer is wrapped in an array of one. */
    private static String buildBody(Customer customer) {
        JSONGenerator generator = JSON.createGenerator(false);
        generator.writeStartArray();
        generator.writeStartObject();
        generator.writeStringField('salesforceId', customer.salesforceId);
        generator.writeStringField('name', customer.name);
        if (customer.country == null) {
            generator.writeNullField('country');
        } else {
            generator.writeStringField('country', customer.country);
        }
        generator.writeEndObject();
        generator.writeEndArray();
        return generator.getAsString();
    }

    /** Plain value snapshot of the created account, so later record changes cannot alter the payload. */
    public class Customer {
        public String salesforceId;
        public String name;
        public String country;

        public Customer(Account account) {
            this.salesforceId = String.valueOf(account.Id);
            this.name = account.Name;
            this.country = String.isBlank(account.BillingCountry) ? null : account.BillingCountry;
        }
    }
}
