/**
 * Publishes Deal_Stage_Change__e platform events for Opportunity records.
 *
 * Each call publishes exactly one event per opportunity and returns the
 * corresponding EventBus.publish results in input order, so callers can
 * determine precisely which event failed.
 */
public class DealEventPublisher {

    // Max events accepted by a single EventBus.publish(List<SObject>) call.
    @TestVisible
    private static final Integer MAX_EVENTS_PER_PUBLISH = 2000;

    /**
     * Publishes one Deal_Stage_Change__e event per opportunity.
     *
     * @param opportunities The opportunities to publish stage change events for.
     *                      Expected to contain at most 200 records (trigger batch size).
     * @return One Database.SaveResult per input opportunity, in the same order as
     *         the input list. An empty or null input list returns an empty list
     *         without publishing anything.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        List<Deal_Stage_Change__e> eventBatch = new List<Deal_Stage_Change__e>();

        for (Opportunity opp : opportunities) {
            eventBatch.add(
                new Deal_Stage_Change__e(
                    Opportunity_Id__c = opp.Id,
                    Stage__c = opp.StageName,
                    Amount__c = opp.Amount
                )
            );

            // Buffer up to MAX_EVENTS_PER_PUBLISH events, then publish in one call.
            if (eventBatch.size() == MAX_EVENTS_PER_PUBLISH) {
                results.addAll(EventBus.publish(eventBatch));
                eventBatch = new List<Deal_Stage_Change__e>();
            }
        }

        if (!eventBatch.isEmpty()) {
            results.addAll(EventBus.publish(eventBatch));
        }

        return results;
    }
}
