import { LightningElement, api } from 'lwc';

/**
 * Keys implemented by the listbox. preventDefault() is called for these keys only,
 * so every other key (notably Tab) keeps its default behaviour.
 */
const HANDLED_KEYS = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

// Option ids must be unique across the document: aria-activedescendant has to
// reference the active option of this instance only.
let instanceCount = 0;

export default class StatusListbox extends LightningElement {
    /** Accessible name of the listbox, rendered as aria-label. */
    @api label;

    /** Unique id prefix for the ids of this instance's options. */
    instanceId = `statusListbox-${(instanceCount += 1)}`;

    _options = [];
    _value;
    _activeIndex = -1;

    /** Options of the list, in order: an array of { value, label }. */
    @api
    get options() {
        return this._options;
    }

    set options(options) {
        // Replacing the list must not move the active option away from the value
        // the user is on, as long as that value is still available.
        const previousActiveValue = this.activeValue;

        this._options = Array.isArray(options) ? options : [];
        this._activeIndex = this.resolveActiveIndex(previousActiveValue);
    }

    /** Selected value; empty when nothing is selected. */
    @api
    get value() {
        return this._value;
    }

    set value(value) {
        this._value = value;

        // The active option follows the selection whenever the parent changes it.
        this._activeIndex = this.resolveActiveIndex(value);
    }

    /** Options with the extra data the template needs. */
    get renderedOptions() {
        return this._options.map((option, index) => {
            const value = option ? option.value : undefined;
            const selected = this.isSelectedValue(value);

            return {
                index,
                id: this.optionId(index),
                value,
                label: option ? option.label : '',
                ariaSelected: selected ? 'true' : 'false',
                className: selected
                    ? 'slds-listbox__option slds-listbox__option_plain slds-is-active'
                    : 'slds-listbox__option slds-listbox__option_plain',
            };
        });
    }

    /** Id of the active option, referenced by aria-activedescendant. */
    get activeOptionId() {
        return this.activeIndex >= 0 ? this.optionId(this.activeIndex) : undefined;
    }

    /** Index of the active option, clamped to the current option list. */
    get activeIndex() {
        const count = this._options.length;

        if (count === 0) {
            return -1;
        }

        return this._activeIndex >= 0 && this._activeIndex < count ? this._activeIndex : 0;
    }

    /** Value of the active option. */
    get activeValue() {
        const option = this._options[this.activeIndex];

        return option ? option.value : undefined;
    }

    /** Builds a unique DOM id for the option at the given index. */
    optionId(index) {
        return `${this.instanceId}-option-${index}`;
    }

    handleKeydown(event) {
        const key = event.key;

        if (!HANDLED_KEYS.includes(key)) {
            return;
        }

        // Only the six keys above are captured, everything else (Tab, Escape, ...)
        // keeps its native behaviour.
        event.preventDefault();

        switch (key) {
            case 'ArrowDown':
                this.setActiveIndex(this.activeIndex + 1);
                break;
            case 'ArrowUp':
                this.setActiveIndex(this.activeIndex - 1);
                break;
            case 'Home':
                this.setActiveIndex(0);
                break;
            case 'End':
                this.setActiveIndex(this._options.length - 1);
                break;
            case 'Enter':
            case ' ':
                this.selectOption(this.activeIndex);
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const index = Number(event.currentTarget.dataset.index);

        if (!Number.isInteger(index) || index < 0 || index >= this._options.length) {
            return;
        }

        // DOM focus stays on the list: the active option is only referenced.
        this.focusListbox();
        this.selectOption(index);
    }

    selectOption(index) {
        const option = this._options[index];

        if (!option) {
            return;
        }

        this.setActiveIndex(index);

        const value = option.value;

        if (this.isSelectedValue(value)) {
            // Already the current selection: the selection does not change, so
            // no change event is dispatched.
            return;
        }

        this._value = value;

        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value },
                bubbles: true,
                composed: true,
            })
        );
    }

    setActiveIndex(index) {
        const count = this._options.length;

        this._activeIndex = count === 0 ? -1 : Math.min(Math.max(index, 0), count - 1);
    }

    resolveActiveIndex(preferredValue) {
        const count = this._options.length;

        if (count === 0) {
            return -1;
        }

        const preferredIndex = this.indexOfValue(preferredValue);

        if (preferredIndex >= 0) {
            return preferredIndex;
        }

        const selectedIndex = this.indexOfValue(this._value);

        return selectedIndex >= 0 ? selectedIndex : 0;
    }

    indexOfValue(value) {
        if (value === undefined || value === null) {
            return -1;
        }

        return this._options.findIndex((option) => option && option.value === value);
    }

    isSelectedValue(value) {
        return value !== undefined && value !== null && value === this._value;
    }

    focusListbox() {
        const listbox = this.template.querySelector('ul');

        if (listbox) {
            listbox.focus();
        }
    }
}
