/**
 * Stages one-off gifts posted to the website as NPSP Data Import records and
 * processes them with NPSP's own data import engine (BDI) through the NPSP Apex API.
 *
 * The class never creates Contacts, Accounts or Opportunities itself. NPSP applies
 * the org's Data Import settings (the npsp__Data_Import_Settings__c hierarchy custom
 * setting - contacts matched on first name, last name and personal email, donations
 * never matched), creates or matches the donor and household, creates the donation,
 * and writes the outcome back onto the Data Import record. Every staged record stays
 * in the org as the audit trail of what was imported.
 */
public with sharing class GiftImportService {

    /** Value for npsp__DataImport__c.npsp__Donation_Donor__c: the gift belongs to Contact1. */
    private static final String DONOR_CONTACT1 = 'Contact1';

    /** npsp__DataImport__c.npsp__Status__c values. */
    private static final String STATUS_TO_BE_IMPORTED = 'To Be Imported';
    private static final String STATUS_IMPORTED = 'Imported';

    /** One gift posted by the website. */
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    /** What happened to one gift. Results are always returned in input order. */
    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    /**
     * Stages one Data Import record per gift and processes them synchronously, in this
     * transaction, with NPSP's Data Import Apex API and the org's Data Import settings.
     * A row NPSP rejects is reported on that row only - the other rows still import.
     *
     * @param gifts the gifts to import; null or empty returns an empty list.
     * @return one ImportResult per gift, in the same order as the input.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // ---- 1. Stage one Data Import record per gift (one bulk DML statement) ----
        List<npsp__DataImport__c> stagedRows = new List<npsp__DataImport__c>();
        // Position of each staged row in the input, so results keep the input order.
        List<Integer> stagedPositions = new List<Integer>();

        for (Integer i = 0; i < gifts.size(); i++) {
            WebGift gift = gifts[i];
            results.add(new ImportResult()); // placeholder, filled in below

            if (gift == null) {
                fillFailure(results[i], 'Gift payload is null.');
                continue;
            }
            stagedRows.add(toDataImport(gift));
            stagedPositions.add(i);
        }

        if (stagedRows.isEmpty()) {
            return results;
        }

        // Persist the audit rows up front: they stay in the org whatever happens next.
        insert stagedRows;

        // ---- 2. Let NPSP import them with its own matching and donation rules ----
        String runError;
        try {
            // One bulk call, so a single call with 200 gifts works: NPSP reads the org's
            // npsp__Data_Import_Settings__c (not overridden here), applies its contact
            // matching, household creation and donation processing rules to every row and
            // writes its outcome back onto the record. A rejected row does not abort the
            // rest of the list - NPSP records the reason on that row.
            npsp.API_DataImport_API.processDataImportRecords(stagedRows);
        } catch (Exception ex) {
            // A thrown exception is a run level problem, not a rejected row: these rows
            // were never finished by NPSP, so their outcome comes from the exception.
            runError = ex.getMessage();
        }

        // ---- 3. Build the results from the Data Import records NPSP updated ----
        Set<Id> stagedIds = new Map<Id, npsp__DataImport__c>(stagedRows).keySet();
        Map<Id, npsp__DataImport__c> processedById = new Map<Id, npsp__DataImport__c>([
            SELECT Id,
                   npsp__Status__c,
                   npsp__FailureInformation__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c
            FROM npsp__DataImport__c
            WHERE Id IN :stagedIds
        ]);

        List<npsp__DataImport__c> unfinished = new List<npsp__DataImport__c>();
        for (Integer i = 0; i < stagedRows.size(); i++) {
            npsp__DataImport__c processed = processedById.get(stagedRows[i].Id);

            if (processed == null) {
                fillFailure(results[stagedPositions[i]], 'Data Import record was not found after processing.');
                continue;
            }

            if (runError != null && !hasOutcome(processed)) {
                // Keep the audit trail complete for rows NPSP never finished.
                processed.npsp__FailureInformation__c = runError;
                unfinished.add(processed);
            }

            results[stagedPositions[i]] = toResult(processed);
        }

        if (!unfinished.isEmpty()) {
            update unfinished; // one bulk DML statement
        }

        return results;
    }

    /** Stages one Data Import record for a gift; NPSP owns all matching and creation rules. */
    private static npsp__DataImport__c toDataImport(WebGift gift) {
        return new npsp__DataImport__c(
            npsp__Contact1_Firstname__c = gift.firstName,
            npsp__Contact1_Lastname__c = gift.lastName,
            npsp__Contact1_Personal_Email__c = gift.email,
            npsp__Donation_Amount__c = gift.amount,
            npsp__Donation_Date__c = gift.giftDate,
            npsp__Donation_Donor__c = DONOR_CONTACT1,
            npsp__Status__c = STATUS_TO_BE_IMPORTED
        );
    }

    /** Reads the outcome NPSP wrote back onto the processed Data Import record. */
    private static ImportResult toResult(npsp__DataImport__c di) {
        ImportResult result = new ImportResult();
        // NPSP marks the rows it imported with the status 'Imported'.
        result.success = STATUS_IMPORTED.equalsIgnoreCase(di.npsp__Status__c);
        result.contactId = di.npsp__Contact1Imported__c;
        result.opportunityId = di.npsp__DonationImported__c;
        if (!result.success) {
            result.errorMessage = di.npsp__FailureInformation__c;
        }
        return result;
    }

    /** True once NPSP has written an outcome (imported, or rejected with its failure information). */
    private static Boolean hasOutcome(npsp__DataImport__c di) {
        return STATUS_IMPORTED.equalsIgnoreCase(di.npsp__Status__c)
            || String.isNotBlank(di.npsp__FailureInformation__c);
    }

    /** Fills a result for a gift that could not even be staged for NPSP. */
    private static void fillFailure(ImportResult result, String message) {
        result.success = false;
        result.errorMessage = message;
    }
}
