/**
 * Registers a family as a single NPSP Household Account.
 *
 * NPSP (Household Account model) creates one household account for every contact
 * that is inserted without an account. Inserting the primary contact on its own
 * therefore yields exactly one real NPSP household: NPSP assigns the Household
 * Account record type, stores the primary contact and runs the automatic
 * household naming, so the account name and the greetings are generated by NPSP.
 * This class never writes Account.Name.
 *
 * The remaining members are inserted with that account Id so NPSP keeps them in
 * the same household instead of creating one household per contact. Exactly one
 * account is created per call, and that account always has members, so no empty
 * or extra household is left behind.
 */
public with sharing class HouseholdService {

    // DeveloperName of the NPSP Household Account record type. Record type Ids
    // are never hard-coded; the record type is resolved/compared by DeveloperName.
    private static final String HOUSEHOLD_ACCOUNT_RT_DEV_NAME = 'HH_Account';

    /**
     * Raised when NPSP is not configured as expected for the Household Account
     * model and therefore no valid household could be produced.
     */
    public class HouseholdServiceException extends Exception {}

    /**
     * Creates one new NPSP Household Account containing all of the given
     * contacts and returns that account's Id.
     *
     * @param  members New contacts (no Id, no AccountId) to register as a single
     *                 family. The first entry becomes the household's primary
     *                 contact.
     * @return Id of the newly created household account.
     * @throws IllegalArgumentException if members is null or empty, or if it
     *         contains a null entry or a contact that already has an Id.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty.');
        }
        for (Contact member : members) {
            if (member == null) {
                throw new IllegalArgumentException('members must not contain null entries.');
            }
            if (member.Id != null) {
                throw new IllegalArgumentException('members must be new contacts without an Id.');
            }
        }

        Contact primary = members[0];

        // 1) Insert the primary contact on its own. NPSP creates exactly one
        //    household account for it (Household Account record type), attaches
        //    the contact to it and generates the household name and greetings.
        //    Any AccountId supplied on the input is ignored on purpose: the
        //    family must live in a brand new household.
        primary.AccountId = null;
        insert primary;

        // 2) Read back the household NPSP created for the primary contact.
        List<Contact> reRead = [
            SELECT AccountId,
                   Account.npe01__One2OneContact__c,
                   Account.RecordType.DeveloperName
            FROM Contact
            WHERE Id = :primary.Id
            LIMIT 1
        ];
        if (reRead.isEmpty()) {
            throw new HouseholdServiceException('The primary contact could not be read back after insert.');
        }
        Contact insertedPrimary = reRead[0];

        Id householdId = insertedPrimary.AccountId;
        if (householdId == null) {
            throw new HouseholdServiceException(
                'NPSP did not create a household account for the primary contact. ' +
                'Check that NPSP is configured for the Household Account model.');
        }
        primary.AccountId = householdId;

        // The account must be a real NPSP household (Household Account record
        // type), otherwise NPSP will not name it or generate the greetings.
        String accountRecordTypeName = (insertedPrimary.Account == null || insertedPrimary.Account.RecordType == null)
            ? null
            : insertedPrimary.Account.RecordType.DeveloperName;
        if (!HOUSEHOLD_ACCOUNT_RT_DEV_NAME.equals(accountRecordTypeName)) {
            throw new HouseholdServiceException(
                'Expected the NPSP Household Account record type ' + HOUSEHOLD_ACCOUNT_RT_DEV_NAME +
                ' but the created account uses record type ' + accountRecordTypeName + '.');
        }

        // 3) Guarantee that the first contact of the list is the household's
        //    primary contact. NPSP normally sets npe01__One2OneContact__c when it
        //    creates the account; this explicit correction keeps the contract
        //    independent of that internal behaviour.
        if (insertedPrimary.Account.npe01__One2OneContact__c != primary.Id) {
            update new Account(Id = householdId, npe01__One2OneContact__c = primary.Id);
        }

        // 4) Add the rest of the family to the same household. AccountId is set
        //    before the insert, so NPSP does not create a household per contact.
        List<Contact> otherMembers = new List<Contact>();
        for (Integer i = 1; i < members.size(); i++) {
            Contact member = members[i];
            member.AccountId = householdId;
            otherMembers.add(member);
        }
        if (!otherMembers.isEmpty()) {
            insert otherMembers;
        }

        return householdId;
    }
}
