/**
 * Credits peer-to-peer fundraisers with NPSP Partial Soft Credits.
 *
 * After addPartialSoftCredits(requests) runs successfully, for every request:
 *   - the contact holds exactly one OpportunityContactRole on the opportunity and
 *     that role's Role equals the requested role. A role that already exists (for
 *     example the "Household Member" role NPSP adds for the donor's household) is
 *     reused and renamed instead of duplicated; surplus roles on the same pair are
 *     removed.
 *   - the contact holds exactly one npsp__Partial_Soft_Credit__c on the opportunity
 *     with the requested amount and the requested role name, linked to the contact
 *     role above through npsp__Contact_Role_ID__c. An existing partial soft credit
 *     is updated in place instead of duplicated.
 *
 * The complete call is validated before any DML: a single invalid request throws
 * SoftCreditException and leaves the org untouched.
 *
 * Governor usage for a full batch of 200 requests: 4 SOQL queries and at most
 * 4 DML statements.
 */
public with sharing class SoftCreditService {

    /** Thrown when a request is invalid. Nothing is changed when it is thrown. */
    public class SoftCreditException extends Exception {}

    /** One fundraiser that should be credited for part of a gift. */
    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    /**
     * Adds (or updates) a partial soft credit for every request. Null or empty
     * input does nothing. Requests must not repeat an opportunity/contact pair.
     */
    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();

        for (SoftCreditRequest request : requests) {
            if (request == null) {
                throw new SoftCreditException('A soft credit request must not be null.');
            }
            if (request.opportunityId == null) {
                throw new SoftCreditException('A soft credit request must specify an opportunity.');
            }
            if (request.contactId == null) {
                throw new SoftCreditException('A soft credit request must specify a contact.');
            }
            opportunityIds.add(request.opportunityId);
            contactIds.add(request.contactId);
        }

        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ]);

        Set<Id> existingContactIds = new Map<Id, Contact>([
            SELECT Id
            FROM Contact
            WHERE Id IN :contactIds
        ]).keySet();

        // Validate the whole call before any DML: one invalid request must leave
        // the org completely unchanged.
        for (SoftCreditRequest request : requests) {
            validateRequest(
                request,
                opportunitiesById.get(request.opportunityId),
                existingContactIds.contains(request.contactId)
            );
        }

        // ---- Contact roles: exactly one per opportunity/contact pair ---------

        Map<String, List<OpportunityContactRole>> rolesByPair =
            new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole existingRole : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds AND ContactId IN :contactIds
        ]) {
            String key = pairKey(existingRole.OpportunityId, existingRole.ContactId);
            List<OpportunityContactRole> pairRoles = rolesByPair.get(key);
            if (pairRoles == null) {
                pairRoles = new List<OpportunityContactRole>();
                rolesByPair.put(key, pairRoles);
            }
            pairRoles.add(existingRole);
        }

        Map<String, OpportunityContactRole> roleByPair =
            new Map<String, OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> surplusRoles = new List<OpportunityContactRole>();

        for (SoftCreditRequest request : requests) {
            String key = pairKey(request.opportunityId, request.contactId);
            List<OpportunityContactRole> pairRoles = rolesByPair.get(key);

            // Prefer an existing role that already carries the requested role name,
            // otherwise adopt an existing role (e.g. "Household Member") and rename it.
            OpportunityContactRole targetRole;
            if (pairRoles != null) {
                for (OpportunityContactRole existingRole : pairRoles) {
                    if (targetRole == null && existingRole.Role == request.role) {
                        targetRole = existingRole;
                    }
                }
                if (targetRole == null) {
                    targetRole = pairRoles[0];
                }
                for (OpportunityContactRole existingRole : pairRoles) {
                    if (existingRole.Id != targetRole.Id) {
                        surplusRoles.add(existingRole);
                    }
                }
            }
            if (targetRole == null) {
                targetRole = new OpportunityContactRole(
                    OpportunityId = request.opportunityId,
                    ContactId = request.contactId
                );
            }
            targetRole.Role = request.role;
            rolesToUpsert.add(targetRole);
            roleByPair.put(key, targetRole);
        }

        if (!surplusRoles.isEmpty()) {
            delete surplusRoles;
        }
        if (!rolesToUpsert.isEmpty()) {
            upsert rolesToUpsert;
        }

        // ---- Partial soft credits: exactly one per opportunity/contact pair ---

        Map<String, List<npsp__Partial_Soft_Credit__c>> creditsByPair =
            new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c existingCredit : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds AND npsp__Contact__c IN :contactIds
        ]) {
            String key = pairKey(existingCredit.npsp__Opportunity__c, existingCredit.npsp__Contact__c);
            List<npsp__Partial_Soft_Credit__c> pairCredits = creditsByPair.get(key);
            if (pairCredits == null) {
                pairCredits = new List<npsp__Partial_Soft_Credit__c>();
                creditsByPair.put(key, pairCredits);
            }
            pairCredits.add(existingCredit);
        }

        List<npsp__Partial_Soft_Credit__c> creditsToUpsert =
            new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> surplusCredits =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest request : requests) {
            String key = pairKey(request.opportunityId, request.contactId);
            List<npsp__Partial_Soft_Credit__c> pairCredits = creditsByPair.get(key);

            // Update the existing credit instead of creating a second one.
            npsp__Partial_Soft_Credit__c targetCredit;
            if (pairCredits != null && !pairCredits.isEmpty()) {
                targetCredit = pairCredits[0];
                for (Integer i = 1; i < pairCredits.size(); i++) {
                    surplusCredits.add(pairCredits[i]);
                }
            } else {
                targetCredit = new npsp__Partial_Soft_Credit__c();
            }

            targetCredit.npsp__Opportunity__c = request.opportunityId;
            targetCredit.npsp__Contact__c = request.contactId;
            targetCredit.npsp__Amount__c = request.amount;
            targetCredit.npsp__Role_Name__c = request.role;
            targetCredit.npsp__Contact_Role_ID__c = roleByPair.get(key).Id;
            if (isContactNameFieldWritable()) {
                targetCredit.npsp__Contact_Name__c = request.contactId;
            }

            creditsToUpsert.add(targetCredit);
        }

        if (!surplusCredits.isEmpty()) {
            delete surplusCredits;
        }
        if (!creditsToUpsert.isEmpty()) {
            upsert creditsToUpsert;
        }
    }

    /** Throws SoftCreditException unless the request can be applied safely. */
    private static void validateRequest(
        SoftCreditRequest request,
        Opportunity opportunity,
        Boolean contactExists
    ) {
        if (opportunity == null) {
            throw new SoftCreditException(
                'Opportunity ' + request.opportunityId + ' does not exist.'
            );
        }
        if (!contactExists) {
            throw new SoftCreditException(
                'Contact ' + request.contactId + ' does not exist.'
            );
        }
        if (opportunity.npsp__Primary_Contact__c == request.contactId) {
            throw new SoftCreditException(
                'Contact ' + request.contactId +
                ' is the primary contact of opportunity ' + request.opportunityId +
                ' and cannot receive a partial soft credit.'
            );
        }
        if (request.amount == null) {
            throw new SoftCreditException('A soft credit request must specify an amount.');
        }
        if (request.amount <= 0) {
            throw new SoftCreditException('A soft credit amount must be greater than zero.');
        }
        if (opportunity.Amount != null && request.amount > opportunity.Amount) {
            throw new SoftCreditException(
                'A soft credit amount of ' + request.amount +
                ' exceeds the opportunity amount of ' + opportunity.Amount + '.'
            );
        }
    }

    /** Keys lookups by opportunity/contact pair; requests never repeat a pair. */
    private static String pairKey(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + ':' + String.valueOf(contactId);
    }

    /** True when the NPSP contact-name field can be written to. */
    private static Boolean isContactNameFieldWritable() {
        SObjectField contactNameField =
            npsp__Partial_Soft_Credit__c.SObjectType.getDescribe()
                .fields.getMap()
                .get('npsp__Contact_Name__c');
        return contactNameField != null && contactNameField.getDescribe().isUpdateable();
    }
}
