```apex
/**
 * Records gifts that have already been received by the nonprofit.
 *
 * Each call records exactly one gift and credits it the way NPSP expects:
 *   - a Closed Won Opportunity on the contact's household account,
 *   - the donor as primary contact with the Donor role, and every other member
 *     of the household with the Household Member role (never more than one
 *     contact role per contact),
 *   - exactly one paid payment for the full amount, dated on the gift date.
 */
public with sharing class GiftService {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String ROLE_DONOR = 'Donor';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';
    private static final String DATE_FORMAT = 'yyyy-MM-dd';

    /**
     * Records a gift that has already been received.
     *
     * @param contactId Id of the donor. The contact must exist and belong to a
     *                  household account.
     * @param amount    The amount received. Must not be null, zero or negative.
     * @param giftDate  The date the gift was received.
     * @return The Id of the Opportunity (gift) that was created.
     * @throws IllegalArgumentException If the contact does not exist, or the
     *         amount is null, zero or negative.
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('giftDate is required.');
        }

        Contact donor = loadDonor(contactId);

        // Keep the gift all-or-nothing: never leave a partially recorded gift behind.
        Savepoint beforeGift = Database.setSavepoint();
        try {
            Opportunity gift = new Opportunity(
                Name = buildGiftName(donor, giftDate),
                AccountId = donor.AccountId,
                StageName = STAGE_CLOSED_WON,
                CloseDate = giftDate,
                Amount = amount,
                npsp__Primary_Contact__c = donor.Id
            );
            insert gift;

            syncContactRoles(gift.Id, donor);
            syncPayment(gift.Id, amount, giftDate);

            return gift.Id;
        } catch (Exception e) {
            Database.rollback(beforeGift);
            throw e;
        }
    }

    /** Loads the donor, failing with IllegalArgumentException when unusable. */
    private static Contact loadDonor(Id contactId) {
        List<Contact> donors = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (donors.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist: ' + contactId);
        }
        Contact donor = donors[0];
        if (donor.AccountId == null) {
            throw new IllegalArgumentException('Contact must belong to a household account.');
        }
        return donor;
    }

    /** Builds "<FirstName> <LastName> Donation <yyyy-MM-dd>". */
    private static String buildGiftName(Contact donor, Date giftDate) {
        String personName = String.isBlank(donor.FirstName)
            ? donor.LastName
            : donor.FirstName + ' ' + donor.LastName;
        String dateText = Datetime.newInstanceGmt(giftDate, Time.newInstance(0, 0, 0, 0))
            .formatGmt(DATE_FORMAT);
        return personName + ' Donation ' + dateText;
    }

    /**
     * Makes the contact roles match NPSP expectations: the donor holds the Donor
     * role and is the primary contact, every other household member holds the
     * Household Member role. No contact may end up with more than one role on the
     * gift, so duplicates (for example ones created by NPSP automation) are
     * collapsed into a single role record.
     */
    private static void syncContactRoles(Id giftId, Contact donor) {
        Map<Id, String> expectedRoles = new Map<Id, String>();
        for (Contact member : [
            SELECT Id
            FROM Contact
            WHERE AccountId = :donor.AccountId
        ]) {
            expectedRoles.put(member.Id, ROLE_HOUSEHOLD_MEMBER);
        }
        expectedRoles.put(donor.Id, ROLE_DONOR);

        Map<Id, List<OpportunityContactRole>> existingByContact =
            new Map<Id, List<OpportunityContactRole>>();
        for (OpportunityContactRole role : [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :giftId
        ]) {
            if (!existingByContact.containsKey(role.ContactId)) {
                existingByContact.put(role.ContactId, new List<OpportunityContactRole>());
            }
            existingByContact.get(role.ContactId).add(role);
        }

        List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toUpsert = new List<OpportunityContactRole>();

        // Exactly one role per contact: keep the first, drop the duplicates.
        for (List<OpportunityContactRole> rolesOfContact : existingByContact.values()) {
            for (Integer i = 1; i < rolesOfContact.size(); i++) {
                toDelete.add(rolesOfContact[i]);
            }
        }

        // Correct the roles that already exist.
        for (Id contactId : existingByContact.keySet()) {
            OpportunityContactRole keep = existingByContact.get(contactId)[0];
            String expectedRole = expectedRoles.get(contactId);
            Boolean isDonor = (contactId == donor.Id);

            if (expectedRole != null) {
                if (keep.Role != expectedRole || keep.IsPrimary != isDonor) {
                    keep.Role = expectedRole;
                    keep.IsPrimary = isDonor;
                    toUpsert.add(keep);
                }
            } else if (keep.IsPrimary == true) {
                keep.IsPrimary = false;
                toUpsert.add(keep);
            }
        }

        // Create the roles that are still missing.
        for (Id contactId : expectedRoles.keySet()) {
            if (existingByContact.containsKey(contactId)) {
                continue;
            }
            toUpsert.add(new OpportunityContactRole(
                OpportunityId = giftId,
                ContactId = contactId,
                Role = expectedRoles.get(contactId),
                IsPrimary = (contactId == donor.Id)
            ));
        }

        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
        if (!toUpsert.isEmpty()) {
            upsert toUpsert;
        }
    }

    /**
     * Guarantees exactly one payment on the gift: paid, for the full amount,
     * dated on the gift date. A payment created by NPSP automation is reused and
     * corrected; any additional payment is deleted so no duplicates remain.
     */
    private static void syncPayment(Id giftId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> existing = [
            SELECT Id
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :giftId
            ORDER BY CreatedDate ASC
        ];

        List<npe01__OppPayment__c> duplicates = new List<npe01__OppPayment__c>();
        for (Integer i = 1; i < existing.size(); i++) {
            duplicates.add(existing[i]);
        }

        npe01__OppPayment__c payment = existing.isEmpty()
            ? new npe01__OppPayment__c(npe01__Opportunity__c = giftId)
            : existing[0];

        payment.npe01__Payment_Amount__c = amount;
        payment.npe01__Payment_Date__c = giftDate;
        payment.npe01__Scheduled_Date__c = giftDate;
        payment.npe01__Paid__c = true;

        if (!duplicates.isEmpty()) {
            delete duplicates;
        }
        if (payment.Id == null) {
            insert payment;
        } else {
            update payment;
        }
    }
}
