  "orgName": "Contoso Service",
  "edition": "Enterprise",
  "features": [
    "ServiceCloud",
    "Knowledge"
  ],
  "settings": {
    "knowledgeSettings": {
      "enableKnowledge": true
    },
    "omniChannelSettings": {
      "enableOmniChannel": true,
      "enableSkillsBasedRouting": true
    }
  }
}
